<?php require_once __DIR__.'/functions.php'; requireAdmin(); $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['delete_product'])){db()->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_POST['delete_product']]);$message='تم حذف المنتج.';}elseif(isset($_POST['status_id'])){db()->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['status_id']]);$message='تم تحديث حالة الطلب.';}elseif(isset($_POST['add_product'])){db()->prepare('INSERT INTO products(category_id,name,slug,description,price,compare_at_price,badge,emoji,accent,stock) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([(int)$_POST['category_id'],trim($_POST['name']),uniqid('item-'),trim($_POST['description']),round((float)$_POST['price']*100),($_POST['compare_at_price']!=='')?round((float)$_POST['compare_at_price']*100):null,trim($_POST['badge']),trim($_POST['emoji'])?:'✨',trim($_POST['accent'])?:'#dceba5',(int)$_POST['stock']]);$message='تمت إضافة المنتج.';}} $cats=db()->query('SELECT * FROM categories ORDER BY id')->fetchAll();$items=db()->query('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();$orders=db()->query('SELECT * FROM orders ORDER BY id DESC LIMIT 50')->fetchAll(); ?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>لوحة الإدارة | نُقطة</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="container nav"><a class="logo" href="index.php">نُقطة <span>•</span></a><a class="cart" href="admin-logout.php">تسجيل الخروج</a></header><main class="container" style="padding:20px 0 80px"><h1>لوحة الإدارة</h1><?php if($message):?><div class="summary"><?=e($message)?></div><?php endif;?><section class="form-wrap" style="max-width:none"><h2>إضافة منتج</h2><form method="post"><input type="hidden" name="add_product" value="1"><div class="form-grid"><div class="field"><label>اسم المنتج</label><input name="name" required></div><div class="field"><label>السعر بالريال</label><input name="price" type="number" step="0.01" required></div><div class="field"><label>التصنيف</label><select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>المخزون</label><input name="stock" type="number" value="20"></div><div class="field"><label>شارة المنتج</label><input name="badge"></div><div class="field"><label>الإيموجي</label><input name="emoji" value="✨"></div><div class="field full"><label>الوصف</label><textarea name="description" required></textarea></div></div><button class="btn">إضافة المنتج</button></form></section><section class="form-wrap" style="max-width:none"><h2>المنتجات (<?=count($items)?>)</h2><?php foreach($items as $p):?><div class="summary" style="display:flex;justify-content:space-between;align-items:center;gap:12px"><span><?=e($p['emoji'])?> <strong><?=e($p['name'])?></strong> · <?=money((int)$p['price'])?> · مخزون <?=$p['stock']?></span><form method="post"><button class="filter" name="delete_product" value="<?=$p['id']?>" onclick="return confirm('حذف المنتج؟')">حذف</button></form></div><?php endforeach;?></section><section class="form-wrap" style="max-width:none"><h2>آخر الطلبات</h2><?php foreach($orders as $o):?><div class="summary"><strong>#<?=$o['id']?> · <?=e($o['customer_name'])?></strong> · <?=money((int)$o['total'])?> · <?=e($o['phone'])?><form method="post" style="display:flex;gap:8px;margin-top:8px"><input type="hidden" name="status_id" value="<?=$o['id']?>"><select name="status"><option value="pending" <?=$o['status']==='pending'?'selected':''?>>جديد</option><option value="confirmed" <?=$o['status']==='confirmed'?'selected':''?>>مؤكد</option><option value="shipped" <?=$o['status']==='shipped'?'selected':''?>>تم الشحن</option><option value="delivered" <?=$o['status']==='delivered'?'selected':''?>>مكتمل</option><option value="cancelled" <?=$o['status']==='cancelled'?'selected':''?>>ملغى</option></select><button class="filter">حفظ الحالة</button></form></div><?php endforeach;?></section></main></body></html>
